{"command":"python3 - <<'PY'
import json
from pathlib import Path
report_path = Path('/root/diagpanel_policy_report.json')
summary_path = Path('/root/diagpanel_policy_summary.md')
with report_path.open() as f:
    r = json.load(f)
with open('/root/report_template.json') as f:
    t = json.load(f)
assert r['metadata'] == t['metadata'], 'metadata mismatch'
assert r['audit_notes'] == t['audit_notes'], 'audit_notes mismatch'
assert set(r) == {'metadata','audit_notes','analysis'}
analysis = r['analysis']
assert set(analysis) == {'assumptions','panels','totals','recommendation'}
panel_codes = [p['panel_code'] for p in analysis['panels']]
assert panel_codes == sorted(panel_codes), panel_codes
assert panel_codes == ['DP-ALPHA','DP-BETA','DP-DELTA','DP-EPS','DP-GAMMA'], panel_codes
required_panel_keys = {'panel_code','panel_name','base_payment_per_run_per_lab_usd','network_adjustment_per_run_per_lab_usd','total_payment_per_run_per_lab_usd','active_labs','shipper_class','shipper_cost_usd','reagent_cost_per_1000_tests_usd','margin_14_day','margin_28_day','annual_margin_difference_28_minus_14_usd'}
required_period_keys = {'runs','tests_per_lab_per_run','annual_revenue_usd','annual_reagent_cost_usd','annual_shipper_cost_usd','annual_margin_usd'}
for p in analysis['panels']:
    assert set(p) == required_panel_keys, p['panel_code']
    assert isinstance(p['active_labs'], int)
    for k in ['margin_14_day','margin_28_day']:
        assert set(p[k]) == required_period_keys, (p['panel_code'], k)
    for key, value in p.items():
        if key.endswith('_usd'):
            assert isinstance(value, (int,float)) and round(value,2) == value
    for block in (p['margin_14_day'], p['margin_28_day']):
        for key, value in block.items():
            if key.endswith('_usd'):
                assert isinstance(value, (int,float)) and round(value,2) == value
for key in ['total_annual_margin_14_day_usd','total_annual_margin_28_day_usd','total_annual_margin_difference_28_minus_14_usd','absolute_total_margin_difference_usd']:
    assert key in analysis['totals']
    assert round(analysis['totals'][key],2) == analysis['totals'][key]
assert analysis['recommendation']['decision'] in {'adopt_28_day','keep_14_day'}
lines = [line for line in summary_path.read_text().splitlines() if line.strip()]
assert 4 <= len(lines) <= 8
assert any('26185.96' in line for line in lines)
assert any('10454.66' in line for line in lines)
assert any('15731.30' in line for line in lines)
assert any('keep_14_day' in line for line in lines)
print('validation ok')
print('panels:', panel_codes)
print('summary lines:', len(lines))
